<?php
// ═══════════════════════════════════════════════════════════
//  The News Desk — Articles API
//
//  GET    /api/articles.php              → published articles only
//  GET    /api/articles.php?id=X         → single article
//  GET    /api/articles.php?admin=1      → all articles incl. drafts (auth required)
//  POST   /api/articles.php              → create (auth required)
//  PUT    /api/articles.php              → update (auth required, partial-safe)
//  DELETE /api/articles.php?id=X         → delete (auth required)
//  POST   /api/articles.php?action=view&id=X → increment view count
// ═══════════════════════════════════════════════════════════

session_start();
require_once '../config.php';
setCorsHeaders();

$method = $_SERVER['REQUEST_METHOD'];
$id     = isset($_GET['id']) ? (int)$_GET['id'] : 0;
$action = $_GET['action'] ?? '';
$db     = getDB();

// One-time migration: add last_edited column if it doesn't exist
try {
    $db->exec('ALTER TABLE articles ADD COLUMN IF NOT EXISTS last_edited DATETIME NULL DEFAULT NULL');
    $db->exec('ALTER TABLE articles ADD COLUMN IF NOT EXISTS copyright_email VARCHAR(255) NULL DEFAULT NULL');
} catch (\Exception $e) { /* already exists or unsupported — safe to ignore */ }

// ── Ensure article IDs look large (start at 237891+) ─────
try {
    $ai = $db->query("SELECT AUTO_INCREMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'articles'")->fetchColumn();
    if ($ai !== false && (int)$ai < 237891) {
        $db->exec("ALTER TABLE articles AUTO_INCREMENT = 237891");
    }
} catch (\Exception $e) { /* ignore if information_schema unavailable */ }

// ── View count increment (public, no auth) ────────────────
if ($method === 'POST' && $action === 'view' && $id > 0) {
    $db->prepare('UPDATE articles SET views = views + 1 WHERE id = ?')->execute([$id]);
    echo json_encode(['success' => true]);
    exit;
}

// ── GET ───────────────────────────────────────────────────
if ($method === 'GET') {
    $isAdmin = !empty($_GET['admin']) && !empty($_SESSION['user']);

    if ($id > 0) {
        // Single article — always return regardless of published status
        $stmt = $db->prepare('SELECT * FROM articles WHERE id = ?');
        $stmt->execute([$id]);
        $article = $stmt->fetch();
        if (!$article) { http_response_code(404); echo json_encode(['error' => 'Not found']); exit; }
        echo json_encode(formatArticle($article));
        exit;
    }

    // All articles — always merge demo articles with DB articles
    if ($isAdmin) {
        // Admin: ALL DB articles (incl. drafts) + all demo/archive articles
        $stmt = $db->query('SELECT * FROM articles ORDER BY date DESC');
        $rows = $stmt->fetchAll();
        $result = array_merge(getDemoArticles(), getChrisMorganArticles(), getArchiveArticles(), getNewsArticles(), array_map('formatArticle', $rows));
    } else {
        // Public: published DB articles + demo articles + Chris Morgan archive + news articles
        $stmt = $db->query('SELECT * FROM articles WHERE published = 1 ORDER BY date DESC');
        $rows = $stmt->fetchAll();
        $result = array_merge(getDemoArticles(), getChrisMorganArticles(), getArchiveArticles(), getNewsArticles(), array_map('formatArticle', $rows));
    }
    // Sort merged list by date descending
    usort($result, function($a, $b) {
        return strtotime($b['date']) - strtotime($a['date']);
    });
    echo json_encode(array_values($result));
    exit;
}

// ── POST (create) ─────────────────────────────────────────
if ($method === 'POST') {
    requireAuth();
    $body = json_decode(file_get_contents('php://input'), true) ?? [];

    $title = trim($body['title'] ?? '');
    $cat   = trim($body['cat']   ?? '');
    if (!$title || !$cat) {
        http_response_code(400);
        echo json_encode(['error' => 'Title and category are required']);
        exit;
    }

    // Safe date parsing — never pass empty/false to date()
    $dateRaw = $body['date'] ?? '';
    if (!empty($dateRaw) && ($ts = strtotime($dateRaw)) !== false) {
        $dateVal = date('Y-m-d H:i:s', $ts);
    } else {
        $dateVal = date('Y-m-d H:i:s');
    }

    // Safe last_edited parsing
    $lastEditedRaw = $body['last_edited'] ?? '';
    if (!empty($lastEditedRaw) && ($ts2 = strtotime($lastEditedRaw)) !== false) {
        $lastEditedVal = date('Y-m-d H:i:s', $ts2);
    } else {
        $lastEditedVal = null;
    }

    $stmt = $db->prepare(
        'INSERT INTO articles (title, excerpt, content, category, author, image, tags, published, featured, breaking, date, last_edited, copyright_email)
         VALUES (:title, :exc, :body, :cat, :author, :img, :tags, :pub, :feat, :brk, :date, :last_edited, :copyright_email)'
    );
    $stmt->execute([
        'title'      => $title,
        'exc'        => trim($body['exc']    ?? ''),
        'body'       => trim($body['body']   ?? ''),
        'cat'        => $cat,
        'author'     => trim($body['author'] ?? 'Staff Reporter') ?: 'Staff Reporter',
        'img'        => trim($body['img']    ?? ''),
        'tags'       => is_array($body['tags'] ?? null) ? implode(',', $body['tags']) : trim($body['tags'] ?? ''),
        'pub'        => isset($body['pub']) ? (int)(bool)$body['pub'] : (isset($body['published']) ? (int)(bool)$body['published'] : 1),
        'feat'       => (int)(bool)($body['feat']    ?? $body['featured'] ?? false),
        'brk'        => (int)(bool)($body['brk']     ?? $body['breaking'] ?? false),
        'date'            => $dateVal,
        'last_edited'     => $lastEditedVal,
        'copyright_email' => trim($body['copyright_email'] ?? '') ?: null,
    ]);

    $newId   = (int)$db->lastInsertId();
    $fetchSt = $db->prepare('SELECT * FROM articles WHERE id = ?');
    $fetchSt->execute([$newId]);
    echo json_encode(['success' => true, 'article' => formatArticle($fetchSt->fetch())]);
    exit;
}

// ── PUT (update) — partial-safe: missing fields keep existing values ──
if ($method === 'PUT') {
    requireAuth();
    $body = json_decode(file_get_contents('php://input'), true) ?? [];
    $id   = (int)($body['id'] ?? 0);
    if (!$id) { http_response_code(400); echo json_encode(['error' => 'Article ID required']); exit; }

    // Fetch existing row so partial updates (e.g. togglePublish) don't wipe fields
    $check = $db->prepare('SELECT * FROM articles WHERE id = ?');
    $check->execute([$id]);
    $existing = $check->fetch();
    if (!$existing) { http_response_code(404); echo json_encode(['error' => 'Article not found']); exit; }

    // Safe date parsing
    $dateRaw = $body['date'] ?? '';
    if (!empty($dateRaw) && ($ts = strtotime($dateRaw)) !== false) {
        $dateVal = date('Y-m-d H:i:s', $ts);
    } else {
        // Keep existing date if none provided
        $dateVal = $existing['date'];
    }

    // Safe last_edited parsing
    $lastEditedRaw2 = $body['last_edited'] ?? '';
    if (array_key_exists('last_edited', $body)) {
        // Explicitly supplied — use it (or null if empty/invalid)
        if (!empty($lastEditedRaw2) && ($ts3 = strtotime($lastEditedRaw2)) !== false) {
            $lastEditedVal2 = date('Y-m-d H:i:s', $ts3);
        } else {
            $lastEditedVal2 = null;
        }
    } else {
        // Not supplied — keep existing value
        $lastEditedVal2 = $existing['last_edited'] ?? null;
    }

    // Merge supplied fields with existing values
    $merged = [
        'title'  => isset($body['title'])  ? trim($body['title'])  : $existing['title'],
        'exc'    => isset($body['exc'])    ? trim($body['exc'])    : $existing['excerpt'],
        'body'   => isset($body['body'])   ? trim($body['body'])   : $existing['content'],
        'cat'    => isset($body['cat'])    ? trim($body['cat'])    : $existing['category'],
        'author' => isset($body['author']) ? (trim($body['author']) ?: 'Staff Reporter') : $existing['author'],
        'img'    => isset($body['img'])    ? trim($body['img'])    : $existing['image'],
        'tags'   => isset($body['tags'])
                        ? (is_array($body['tags']) ? implode(',', $body['tags']) : trim($body['tags']))
                        : $existing['tags'],
        'pub'    => isset($body['pub'])
                        ? (int)(bool)$body['pub']
                        : (isset($body['published']) ? (int)(bool)$body['published'] : (int)$existing['published']),
        'feat'   => isset($body['feat'])
                        ? (int)(bool)$body['feat']
                        : (isset($body['featured']) ? (int)(bool)$body['featured'] : (int)$existing['featured']),
        'brk'    => isset($body['brk'])
                        ? (int)(bool)$body['brk']
                        : (isset($body['breaking']) ? (int)(bool)$body['breaking'] : (int)$existing['breaking']),
        'date'            => $dateVal,
        'last_edited'     => $lastEditedVal2,
        'views'           => (int)($existing['views'] ?? 0),
        'copyright_email' => isset($body['copyright_email'])
                                ? (trim($body['copyright_email']) ?: null)
                                : ($existing['copyright_email'] ?? null),
    ];

    // Full edit (has title/body fields) → delete old row, insert fresh to get new ascending ID
    // Simple toggle (only pub flag) → plain UPDATE to avoid churning the URL
    $isFullEdit = isset($body['title']) || isset($body['body']) || isset($body['exc']);

    if ($isFullEdit) {
        $db->prepare('DELETE FROM articles WHERE id = ?')->execute([$id]);
        $ins = $db->prepare(
            'INSERT INTO articles (title, excerpt, content, category, author, image, tags, published, featured, breaking, date, last_edited, views, copyright_email)
             VALUES (:title, :exc, :body, :cat, :author, :img, :tags, :pub, :feat, :brk, :date, :last_edited, :views, :copyright_email)'
        );
        $ins->execute($merged);
        $newId = (int)$db->lastInsertId();
        $fetchSt = $db->prepare('SELECT * FROM articles WHERE id = ?');
        $fetchSt->execute([$newId]);
    } else {
        // Toggle-publish or other minor flag update — keep same ID
        $stmt = $db->prepare(
            'UPDATE articles SET
                title      = :title,
                excerpt    = :exc,
                content    = :body,
                category   = :cat,
                author     = :author,
                image      = :img,
                tags       = :tags,
                published  = :pub,
                featured   = :feat,
                breaking   = :brk,
                date       = :date,
                last_edited= :last_edited,
            copyright_email= :copyright_email
         WHERE id = :id'
        );
        $stmt->execute(array_merge($merged, ['id' => $id]));
        $fetchSt = $db->prepare('SELECT * FROM articles WHERE id = ?');
        $fetchSt->execute([$id]);
    }

    echo json_encode(['success' => true, 'article' => formatArticle($fetchSt->fetch())]);
    exit;
}

// ── DELETE ────────────────────────────────────────────────
if ($method === 'DELETE') {
    requireAuth();
    if (!$id) { http_response_code(400); echo json_encode(['error' => 'Article ID required']); exit; }

    $check = $db->prepare('SELECT id FROM articles WHERE id = ?');
    $check->execute([$id]);
    if (!$check->fetch()) { http_response_code(404); echo json_encode(['error' => 'Article not found']); exit; }

    $db->prepare('DELETE FROM articles WHERE id = ?')->execute([$id]);
    echo json_encode(['success' => true, 'deleted' => $id]);
    exit;
}

http_response_code(405);
echo json_encode(['error' => 'Method not allowed']);

